import javafx.application.Application;
import javafx.collections.*;
import javafx.concurrent.Task;
import javafx.geometry.Insets;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.*;
import java.io.File;
import java.nio.file.*;
import java.util.List;

public class ImportApp extends Application {
    @Override
    public void start(Stage stage) {
        Button choose = new Button("Choose CSV..."), cancel = new Button("Cancel");
        ProgressBar bar = new ProgressBar(0); bar.setMaxWidth(Double.MAX_VALUE);
        Label status = new Label("Idle");
        ListView<String> failures = new ListView<>(FXCollections.observableArrayList());
        cancel.setDisable(true);

        choose.setOnAction(e -> {
            File file = new FileChooser().showOpenDialog(stage);
            if (file == null) return;
            Task<Integer> task = new Task<>() {
                @Override protected Integer call() throws Exception {
                    List<String> lines = Files.readAllLines(file.toPath());
                    int ok = 0;
                    for (int i = 0; i < lines.size(); i++) {
                        if (isCancelled()) { updateMessage("Cancelled at row " + i); break; }
                        String[] cols = lines.get(i).split(",");
                        if (cols.length < 2) { final String bad = "Row " + (i + 1) + ": " + lines.get(i); javafx.application.Platform.runLater(() -> failures.getItems().add(bad)); }
                        else ok++;
                        updateProgress(i + 1, lines.size());
                        updateMessage("Processed " + (i + 1) + " of " + lines.size());
                        Thread.sleep(2);                         // simulate work
                    }
                    return ok;
                }
            };
            bar.progressProperty().bind(task.progressProperty());
            status.textProperty().bind(task.messageProperty());
            choose.disableProperty().bind(task.runningProperty());
            cancel.disableProperty().bind(task.runningProperty().not());
            cancel.setOnAction(ev -> task.cancel());
            task.setOnSucceeded(ev -> status.textProperty().unbind());
            task.setOnFailed(ev -> new Alert(Alert.AlertType.ERROR, String.valueOf(task.getException().getMessage())).show());
            Thread t = new Thread(task, "csv-import"); t.setDaemon(true); t.start();
        });

        VBox root = new VBox(8, new HBox(8, choose, cancel), bar, status, new Label("Rejected rows"), failures);
        root.setPadding(new Insets(12));
        VBox.setVgrow(failures, Priority.ALWAYS);
        stage.setScene(new Scene(root, 520, 380));
        stage.setTitle("CSV Import");
        stage.show();
    }
    public static void main(String[] args) { launch(args); }
}

// collect failures off-thread and publish once
List<String> rejected = new ArrayList<>();
// ... inside call(): rejected.add(bad);
task.setOnSucceeded(ev -> failures.getItems().setAll(rejected));        // single UI update

public record ImportResult(int imported, List<String> rejected) {}
public class CsvImporter {
    public ImportResult run(Path file, BiConsumer<Integer, Integer> progress, BooleanSupplier cancelled) throws IOException {
        List<String> rejected = new ArrayList<>(); int ok = 0, row = 0;
        try (var lines = Files.lines(file)) {
            for (String line : (Iterable<String>) lines::iterator) {
                if (cancelled.getAsBoolean()) break;
                row++;
                if (line.split(",").length < 2) rejected.add("Row " + row + ": " + line); else ok++;
                progress.accept(row, -1);
            }
        }
        return new ImportResult(ok, rejected);
    }
}

// ViewModel: pure Java with properties, no JavaFX controls, so it is unit-testable
public class InventoryViewModel {
    private final ObservableList<ProductRow> products = FXCollections.observableArrayList();
    private final StringProperty search = new SimpleStringProperty("");
    private final BooleanProperty busy = new SimpleBooleanProperty();
    private final StringProperty status = new SimpleStringProperty("Ready");
    private final FilteredList<ProductRow> visible = new FilteredList<>(products, p -> true);
    private final InventoryService service; private final Executor background;

    public InventoryViewModel(InventoryService service, Executor background) {
        this.service = service; this.background = background;
        search.addListener((o, a, q) -> visible.setPredicate(p -> q.isBlank() || p.name().toLowerCase().contains(q.toLowerCase()) || p.barcode().equals(q)));
    }
    public void load() { run("Loading...", service::findAll, rows -> products.setAll(rows)); }
    public void adjustStock(ProductRow row, int delta) { run("Saving...", () -> service.adjust(row.id(), delta), updated -> { int i = products.indexOf(row); products.set(i, updated); }); }

    private <T> void run(String message, Callable<T> work, Consumer<T> onSuccess) {
        busy.set(true); status.set(message);
        Task<T> task = new Task<>() { protected T call() throws Exception { return work.call(); } };
        task.setOnSucceeded(e -> { busy.set(false); status.set("Done"); onSuccess.accept(task.getValue()); });
        task.setOnFailed(e -> { busy.set(false); status.set("Failed: " + task.getException().getMessage()); });
        background.execute(task);
    }
    public ObservableList<ProductRow> visibleProducts() { return visible; }
    public StringProperty searchProperty() { return search; }
    public BooleanProperty busyProperty() { return busy; }
    public StringProperty statusProperty() { return status; }
}

public Product adjust(long id, int delta) throws SQLException {
    try (Connection con = ds.getConnection()) {
        con.setAutoCommit(false);
        try {
            int changed = update(con, "update product set stock = stock + ? where id = ? and stock + ? >= 0", delta, id, delta);
            if (changed == 0) throw new InsufficientStockException(id);
            update(con, "insert into sync_outbox(product_id, delta, created_at) values (?, ?, ?)", id, delta, Instant.now().toString());
            con.commit();
            return find(con, id);
        } catch (Exception e) { con.rollback(); throw e; }
    }
}

